/**
 * Content script: when the theme runs at the top level (theme.betterroblox.com or
 * local Vite), window.parent === window. Roblox-side postMessage listeners never
 * run, so API/storage bridge calls time out. This script mirrors the Roblox parent
 * bridge from loader.js + messageHandler.js for direct debugging (Performance tab, etc.).
 */
import { handleMessage, initMessageHandler } from "./messageHandler.js";

function sendToPage(type, payload = {}, event = null) {
  if (!payload) {
    payload = {};
  }
  if (
    event &&
    event.data &&
    event.data.payload &&
    typeof event.data.payload._requestId === "number"
  ) {
    payload._responseToId = event.data.payload._requestId;
  }
  window.postMessage({ type, payload }, "*");
}

initMessageHandler(sendToPage);

window.addEventListener("message", (event) => {
  if (event.source !== window) return;
  if (event.origin !== window.location.origin) return;
  void handleMessage(event).catch((err) => {
    console.error("[BetterBLOX theme standalone bridge]", err);
  });
});
