import { getData, setData, deleteData } from "./storageManager.js";
import {
  getActiveAccount,
  getAllAccounts,
  setActiveAccount,
  removeAccount,
} from "./accountManager.js";

let _sendToIframe = (type, payload, event) => {
  console.debug("[BETTERBLOX - Bridge] V2 Iframe is not initialized");
};

export async function initMessageHandler(sendToIframe) {
  _sendToIframe = sendToIframe;
}

/**
 * Handles messages that expect a response (with request ID)
 * @param {string} type - Message type
 * @param {Object} payload - Message payload
 * @param {string} responseType - Response message type
 * @param {MessageEvent} event - Original message event
 */
export async function handleWaitedEvents(type, payload, responseType, event) {
  switch (type) {
    case "GET_RBLX_ACC":
      console.error("[BETTERBLOX] Method forbidden");
      break;
    case "GET_DATA":
      if (
        payload.key === ".ROBLOSECURITY" ||
        payload.key === "roblox-accounts"
      ) {
        console.error("[BETTERBLOX] Method forbidden!");
        break;
      }

      const data = await getData(payload.key);

      if (payload.key === "activeAccount") {
        if (data?.cookie) delete data?.cookie;
      }

      _sendToIframe(responseType, { data }, event);
      break;

    case "SET_DATA":
      const saveResult = await setData(payload.key, payload.data);
      _sendToIframe(responseType, { success: saveResult }, event);
      break;

    case "DELETE_DATA":
      const deleteResult = await deleteData(payload.key);
      _sendToIframe(responseType, { success: deleteResult }, event);
      break;

    case "SET_ACTIVE_ACCOUNT":
      await setData("activeAccount", payload.data);
      const account = await setActiveAccount(payload?.data?.id);
      _sendToIframe(responseType, { success: true }, event);
      break;

    case "GET_ACTIVE_ACCOUNT":
      const activeAccount = await getActiveAccount();
      if (activeAccount?.cookie) delete activeAccount?.cookie;
      _sendToIframe(responseType, { data: activeAccount ?? null }, event);
      break;

    case "GET_ACCOUNTS":
      const accounts = await getAllAccounts();
      accounts.forEach((account) => {
        if (account?.cookie) delete account?.cookie;
      });
      _sendToIframe(responseType, { data: accounts }, event);
      break;

    case "REMOVE_ROBLOX_ACCOUNT":
      await removeAccount(payload?.data?.id);
      _sendToIframe(responseType, { success: true }, event);
      break;

    case "API_REQUEST":
      const backgroundResponse = await chrome.runtime.sendMessage({
        type: type,
        data: payload,
      });
      _sendToIframe(responseType, { data: backgroundResponse }, event);
      break;
    default:
      console.warn(
        "UNHANDLED Message from iframe sended to background:",
        type,
        payload,
      );
      const response = await chrome.runtime.sendMessage({
        type: type,
        data: payload,
      });
      _sendToIframe(responseType, { data: response }, event);
      break;
  }
}

/**
 * Handles messages that don't expect a response (no request ID)
 * @param {string} type - Message type
 * @param {Object} payload - Message payload
 */
export async function handleUnwaitedEvents(type, payload) {
  switch (type) {
    case "GET_RBLX_ACC":
      console.error("[BETTERBLOX] Method forbidden");
      break;
    case "CHILD_READY":
      console.log("Iframe is ready:", payload);
      break;

    case "ADD_ROBLOX_ACCOUNT":
      console.log("Adding Roblox account:", payload);
      window.open("https://www.roblox.com/Login", "_blank");
      break;

    // Add any other message types that don't need request ID tracking

    default:
      console.log("Message from iframe:", type, payload);
  }
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  _sendToIframe("BACKGROUND_MESSAGE", message);
});

/**
 * Main message handler function
 * @param {MessageEvent} event - The message event
 */
export async function handleMessage(event) {
  const { type, payload } = event.data;
  if (!type || !payload) return;

  const hasRequestId = payload && typeof payload._requestId === "number";
  // Generate response type by adding _RESPONSE suffix
  const responseType = type + "_RESPONSE";

  // Route to appropriate handler based on whether it has a request ID
  if (hasRequestId) {
    await handleWaitedEvents(type, payload, responseType, event);
  } else {
    await handleUnwaitedEvents(type, payload);
  }
}
